//! The GUI's fixture projects (docs/GUI.md G§8.4): the core's sample
//! projects written to disk with real media, generated by ffmpeg and
//! cached ([`fixture`]: `testsrc2`, whose corner shows the time and the
//! frame number, and a 440 Hz tone gated by speech intervals), on the fake
//! backend's sources.
//!
//! - [`design_fixture`]: BRIEF §3's `rust-traits-talk` ([`DesignVariant`]):
//!   `qrec clip list` is BRIEF §3.3; take 9 is broken with the EOS timeout,
//!   take 7 recovered, take 6 tooShort; autocut on c3e9 plans BRIEF §3.6's
//!   four regions and finds BRIEF §3.3's two silences in c2d0.
//! - [`perf_fixture`]: a long timeline for the performance probes (G§8.6).
//! - [`playback_fixture`]: WP1's playback measurement (G§3.10).
//! - [`write_ui`]: a case's `.qrec/ui.json` preset (playhead, selection,
//!   zoom, scroll, canvas mode, bin), written before launch.
//!
//! The take files are named as the fake backend records them
//! (`L1-screen-FAKE-1.mkv`, `L2-camera-0.mkv`, `A1-mic.mka`,
//! `A2-system.mka`) and their facts describe the generated media (screens
//! 640×360, the camera 320×240), not BRIEF's native sizes. No history is
//! written (take 2 reads "Removed from the timeline." in the bin).

use std::fs;
use std::path::Path;

use chrono::{DateTime, Utc};
use qrec_core::TakeId;
use qrec_core::capture_plan::{audio_file_name, video_file_name};
use qrec_core::model::{AudioRole, Clip, Fps, Project, Rect, StreamKind, Take, VideoSource};
use qrec_core::state::UiState;
use qrec_core::testkit::{ProjectBuilder, design_project, perf_project};
use qrec_core::time::{NS_PER_MS, frame_ns};

use super::media::{MediaSpec, fixture};
use super::project::write_project;
use crate::capture::fake::{FAKE_CAMERA, FAKE_MIC, FAKE_MONITOR, FAKE_SCREENS};

/// Which state of BRIEF's sample project (G§8.4).
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum DesignVariant {
    /// BRIEF §3: takes 1–9, the 10 clips c7f3 … c3e9.
    Base,
    /// `Base` plus take 10 (4,842 frames, recorded at 14:38) placed as the
    /// 11th clip `c5e1` (S05b).
    Take10Landed,
    /// `Base` with take 5's L2 missing: no stream, no file (S13b's
    /// "Missing in this take", C16's missing-media clip).
    MissingL2,
    /// `Base`'s scene and takes on a 3-clip, 90-frame timeline (c7f3, c1b2
    /// and c3e9, 30 frames each), so a Draft export takes seconds (the
    /// smoke run, S16, S16b).
    Smoke,
}

/// The size the fixtures record screens at.
pub const SCREEN_SIZE: (u32, u32) = (640, 360);
/// The size the fixtures record cameras at.
pub const CAMERA_SIZE: (u32, u32) = (320, 240);
/// Take 10 of [`DesignVariant::Take10Landed`]: its clip.
pub const TAKE_10_CLIP: &str = "c5e1";
/// Take 10's length: `00:02:41:12`, the S04 timer.
pub const TAKE_10_FRAMES: u64 = 4842;

/// The silences on A1 of the design takes, in file milliseconds (speech,
/// the tone, everywhere else). Autocut's 120 ms padding shrinks each to a
/// span that starts and ends mid-frame, so ffmpeg's sample-exact edges
/// never flip a frame:
/// - take 8: BRIEF §3.6's four regions of c3e9 (take frames 556–604,
///   1284–1326, 1990–2029, 2662–2719: 48, 42, 39 and 57 frames);
/// - take 5: BRIEF §3.3's two silences inside c2d0 (00:01:13:02–00:01:14:10
///   and 00:01:18:20–00:01:19:05: take frames 120–158 and 288–303), which
///   S08 hatches;
/// - takes 1 and 3: the gaps between their clips (each silence covers its
///   gap plus 100 ms, so autocut leaves the clips as they are).
fn design_silences_ms(take: u32) -> &'static [(u64, u64)] {
    match take {
        1 => &[(13_567, 15_267)],
        3 => &[
            (8_833, 10_233),
            (20_267, 21_833),
            (29_567, 31_133),
            (39_233, 40_833),
        ],
        5 => &[(4_000, 5_267), (9_600, 10_100)],
        8 => &[
            (18_397, 20_270),
            (42_663, 44_337),
            (66_197, 67_770),
            (88_597, 90_770),
        ],
        _ => &[],
    }
}

/// Writes BRIEF §3's sample project ([`design_project`]) in `dir`, an
/// empty folder, as `variant`, on the fake backend's sources (L1 "Main
/// screen" on `FAKE-1`, L2 "Face" on `/dev/fake0`, A1 "Yeti Nano" on
/// `alsa_input.fake`, A2 "System audio" on `alsa_output.fake.monitor`), with
/// the media of every take. Returns the project as written.
pub fn design_fixture(dir: &Path, variant: DesignVariant) -> Project {
    let mut project = design_project();
    match variant {
        DesignVariant::Base => {}
        DesignVariant::Take10Landed => land_take_10(&mut project),
        DesignVariant::MissingL2 => {
            let take = project.takes.get_mut(&TakeId::numbered(5)).expect("take 5");
            for layer in take
                .scene
                .layers
                .iter_mut()
                .filter(|l| l.id.as_str() == "L2")
            {
                layer.missing = true;
            }
            take.streams.retain(|s| s.id != "L2");
        }
        DesignVariant::Smoke => {
            project.timeline.clips = [("c7f3", 1), ("c1b2", 3), ("c3e9", 8)]
                .into_iter()
                .map(|(id, take)| Clip {
                    id: id.parse().expect("a clip id"),
                    take: TakeId::numbered(take),
                    in_: 0,
                    out: 30,
                })
                .collect();
        }
    }
    on_fake_sources(&mut project);
    let media = Media {
        screen: SCREEN_SIZE,
        camera: CAMERA_SIZE,
        silences: &|take| design_silences_ms(take.number()).to_vec(),
    };
    write_media(dir, &mut project, &media);
    save(dir, &project);
    project
}

/// Writes [`perf_project`]`(clips)` in `dir`: the design scene on the fake
/// sources, 8 takes of 3,600 frames (two minutes) and `clips` clips. Every
/// take uses the same media (one cached file per kind, linked eight times);
/// A1 speaks 9 s, then is silent 1 s.
pub fn perf_fixture(dir: &Path, clips: usize) -> Project {
    let mut project = perf_project(clips);
    on_fake_sources(&mut project);
    let media = Media {
        screen: SCREEN_SIZE,
        camera: CAMERA_SIZE,
        silences: &|_| {
            (0..12)
                .map(|i| (i * 10_000 + 9_000, i * 10_000 + 10_000))
                .collect()
        },
    };
    write_media(dir, &mut project, &media);
    save(dir, &project);
    project
}

/// Writes WP1's playback measurement project in `dir` (G§3.10): a
/// 1920×1080@30 canvas with two 2560×1440 screens (`FAKE-1` full canvas,
/// `FAKE-2` in the top-right quarter) and a 1280×720 camera, all H.264 at
/// 30 fps, plus a mic and system audio: one 60 s take placed whole. Heavy:
/// the first call generates about a minute of 1440p video.
pub fn playback_fixture(dir: &Path) -> Project {
    let mut project = ProjectBuilder::new()
        .name("playback")
        .canvas(1920, 1080, Fps::new(30, 1))
        .screen_layer("L1", FAKE_SCREENS[0])
        .screen_layer("L2", FAKE_SCREENS[1])
        .camera_layer("L3", FAKE_CAMERA)
        .mic("A1", FAKE_MIC)
        .system("A2", FAKE_MONITOR)
        .take("take-0001", 1800)
        .clip("c001", "take-0001", 0, 1800)
        .build();
    let quarter = Rect::new(960, 0, 960, 540);
    for scene in std::iter::once(&mut project.scene)
        .chain(project.takes.values_mut().map(|take| &mut take.scene))
    {
        if let Some(l2) = scene.layers.iter_mut().find(|l| l.id.as_str() == "L2") {
            l2.rect = quarter;
        }
    }
    for take in project.takes.values_mut() {
        take.placed = true;
    }
    let media = Media {
        screen: (2560, 1440),
        camera: (1280, 720),
        silences: &|_| vec![(20_000, 21_000), (40_000, 41_500)],
    };
    write_media(dir, &mut project, &media);
    save(dir, &project);
    project
}

/// Writes `ui` as the project's `.qrec/ui.json` (what a host reads when it
/// opens the project): a case's preset, before launch.
pub fn write_ui(dir: &Path, ui: &UiState) {
    let qrec = dir.join(".qrec");
    fs::create_dir_all(&qrec).unwrap_or_else(|e| panic!("create {}: {e}", qrec.display()));
    let mut bytes = serde_json::to_vec(ui).expect("ui.json serializes");
    bytes.push(b'\n');
    let path = qrec.join("ui.json");
    fs::write(&path, bytes).unwrap_or_else(|e| panic!("write {}: {e}", path.display()));
}

// ------------------------------------------------------------- building

/// Take 10, recorded at 14:38 in the project scene and placed at the end.
fn land_take_10(project: &mut Project) {
    let id = TakeId::numbered(10);
    let mut take: Take = project
        .takes
        .get(&TakeId::numbered(1))
        .expect("take 1")
        .clone();
    take.recorded_at = "2026-10-14T14:38:00Z"
        .parse::<DateTime<Utc>>()
        .expect("a time");
    take.duration_frames = TAKE_10_FRAMES;
    take.scene = project.scene.clone();
    take.placed = true;
    // Its streams are rewritten below from the scene ([`write_media`]).
    project.takes.insert(id.clone(), take);
    project.timeline.clips.push(Clip {
        id: TAKE_10_CLIP.parse().expect("a clip id"),
        take: id,
        in_: 0,
        out: TAKE_10_FRAMES,
    });
    project.next_take_number = 11;
}

/// The design scene's sources become the fake backend's: screens `DP-4` and
/// `HDMI-A-1` are `FAKE-1` and `FAKE-2`, cameras `/dev/fake0`, the mic
/// `alsa_input.fake`, system audio `alsa_output.fake.monitor`. Names and
/// labels stay BRIEF's (the design inventory reports the same labels).
fn on_fake_sources(project: &mut Project) {
    for scene in std::iter::once(&mut project.scene)
        .chain(project.takes.values_mut().map(|take| &mut take.scene))
    {
        for layer in &mut scene.layers {
            match &mut layer.source {
                VideoSource::Screen { output, .. } => {
                    *output = if output.as_str() == "HDMI-A-1" {
                        FAKE_SCREENS[1]
                    } else {
                        FAKE_SCREENS[0]
                    }
                    .to_owned();
                }
                VideoSource::Camera { device, .. } => *device = FAKE_CAMERA.to_owned(),
            }
        }
        for track in &mut scene.audio {
            track.source = match track.role {
                AudioRole::Mic => FAKE_MIC,
                AudioRole::System => FAKE_MONITOR,
            }
            .to_owned();
        }
    }
}

/// What a fixture records.
struct Media<'a> {
    screen: (u32, u32),
    camera: (u32, u32),
    /// A1's silences per take, in file milliseconds.
    silences: &'a dyn Fn(&TakeId) -> Vec<(u64, u64)>,
}

/// Creates every take's folder with a `recorder.log`, names its streams as
/// the fake backend records them, generates their media and describes it
/// in the stream facts. A broken take keeps no stream.
fn write_media(dir: &Path, project: &mut Project, media: &Media<'_>) {
    let fps = project.canvas.fps;
    for (id, take) in &mut project.takes {
        let take_dir = dir.join("takes").join(id.as_str());
        fs::create_dir_all(&take_dir)
            .unwrap_or_else(|e| panic!("create {}: {e}", take_dir.display()));
        let log = match &take.error {
            Some(error) => format!("qrec fixture: {id} broke: {error}\n"),
            None => format!("qrec fixture: {id} was generated, no recorder ran\n"),
        };
        fs::write(take_dir.join("recorder.log"), log).expect("write the recorder log");
        let frames = take.duration_frames;
        let duration_ms = u64::try_from(frame_ns(frames as i64, fps))
            .expect("a length")
            .div_ceil(NS_PER_MS as u64);
        let Take { scene, streams, .. } = take;
        for stream in streams.iter_mut() {
            let spec = match stream.kind {
                StreamKind::Video => {
                    let layer = scene
                        .layers
                        .iter()
                        .find(|l| l.id.as_str() == stream.id)
                        .unwrap_or_else(|| panic!("{id}: no layer {}", stream.id));
                    let (width, height) = match layer.source {
                        VideoSource::Screen { .. } => media.screen,
                        VideoSource::Camera { .. } => media.camera,
                    };
                    stream.file = format!("takes/{id}/{}", video_file_name(layer));
                    stream.width = Some(width);
                    stream.height = Some(height);
                    stream.sample_rate = None;
                    stream.channels = None;
                    stream.frames = Some(frames);
                    stream.fps = Some(fps);
                    stream.duration_ns = Some(frame_ns(frames as i64, fps));
                    MediaSpec::video(width, height, 30, frames).with_fps(fps)
                }
                StreamKind::Audio => {
                    let track = scene
                        .audio
                        .iter()
                        .find(|t| t.id.as_str() == stream.id)
                        .unwrap_or_else(|| panic!("{id}: no track {}", stream.id));
                    let (channels, speech) = match track.role {
                        AudioRole::Mic => (1, speech_around(&(media.silences)(id), duration_ms)),
                        AudioRole::System => (2, Vec::new()),
                    };
                    stream.file = format!("takes/{id}/{}", audio_file_name(track));
                    stream.width = None;
                    stream.height = None;
                    stream.sample_rate = Some(48_000);
                    stream.channels = Some(channels);
                    stream.frames = None;
                    stream.fps = None;
                    stream.duration_ns = Some(duration_ms as i64 * NS_PER_MS);
                    MediaSpec::audio(48_000, channels, duration_ms, &speech)
                }
            };
            stream.start_offset_ns = 0;
            link(&fixture(&spec), &dir.join(&stream.file));
        }
    }
}

/// Speech everywhere in `[0, duration_ms)` except `silences` (sorted,
/// disjoint).
fn speech_around(silences: &[(u64, u64)], duration_ms: u64) -> Vec<(u64, u64)> {
    let mut speech = Vec::new();
    let mut cursor = 0;
    for &(start, end) in silences {
        let (start, end) = (start.min(duration_ms), end.min(duration_ms));
        if start > cursor {
            speech.push((cursor, start));
        }
        cursor = cursor.max(end);
    }
    if cursor < duration_ms {
        speech.push((cursor, duration_ms));
    }
    speech
}

/// `qrec.json`, pretty-printed like [`super::fixture_project`]'s.
fn save(dir: &Path, project: &Project) {
    write_project(
        dir,
        &serde_json::to_value(project).expect("a project serializes"),
    );
}

/// A hard link to the cached fixture (a copy across file systems).
fn link(source: &Path, target: &Path) {
    if fs::hard_link(source, target).is_err() {
        fs::copy(source, target)
            .unwrap_or_else(|e| panic!("copy {} to {}: {e}", source.display(), target.display()));
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::testkit::{TestEnv, detect_silences, ffprobe};
    use qrec_core::TakeStatus;
    use qrec_core::on_event::record::EOS_TIMEOUT_REASON;

    #[test]
    fn speech_fills_the_gaps_between_silences() {
        assert_eq!(speech_around(&[], 500), [(0, 500)]);
        assert_eq!(
            speech_around(&[(100, 200), (300, 400)], 500),
            [(0, 100), (200, 300), (400, 500)]
        );
        assert_eq!(speech_around(&[(0, 200), (400, 900)], 500), [(200, 400)]);
    }

    /// Each design silence shrunk by autocut's 120 ms padding starts and
    /// ends at least 10 ms inside a frame, so a sample of jitter at its
    /// edges never moves a cut.
    #[test]
    fn padded_silences_end_mid_frame() {
        for take in [1, 3, 5, 8] {
            for &(start, end) in design_silences_ms(take) {
                for edge in [start + 120, end - 120] {
                    let into_frame = (edge * 30) % 1000;
                    assert!(
                        (300..=700).contains(&into_frame),
                        "take {take}: {edge} ms is {into_frame}/1000 into its frame"
                    );
                }
            }
        }
    }

    /// The fixture's files and facts: what the fake backend would record,
    /// at the fixture sizes; every stream's file is there.
    #[test]
    fn the_design_fixture_is_written_with_its_media() {
        let env = TestEnv::new();
        let dir = env.empty_dir("rust-traits-talk");
        let project = design_fixture(&dir, DesignVariant::Base);
        let on_disk: Project =
            serde_json::from_slice(&fs::read(dir.join("qrec.json")).unwrap()).unwrap();
        assert_eq!(on_disk, project);
        assert!(
            qrec_core::validate::validate(&project)
                .iter()
                .all(|i| { i.severity != qrec_core::validate::Severity::Error })
        );
        let take3 = &project.takes[&TakeId::numbered(3)];
        let files: Vec<&str> = take3.streams.iter().map(|s| s.file.as_str()).collect();
        assert_eq!(
            files,
            [
                "takes/take-0003/L1-screen-FAKE-1.mkv",
                "takes/take-0003/L2-camera-0.mkv",
                "takes/take-0003/A1-mic.mka",
                "takes/take-0003/A2-system.mka",
            ]
        );
        for take in project.takes.values() {
            for stream in &take.streams {
                assert!(dir.join(&stream.file).is_file(), "{}", stream.file);
            }
        }
        assert!(dir.join("takes/take-0009/recorder.log").is_file());
        let take9 = &project.takes[&TakeId::numbered(9)];
        assert_eq!(take9.status, TakeStatus::Broken);
        assert_eq!(take9.error.as_deref(), Some(EOS_TIMEOUT_REASON));
        assert!(take9.streams.is_empty());
        // The sources are the fake backend's.
        let scene = serde_json::to_value(&project.scene).unwrap();
        assert_eq!(scene["layers"][0]["source"]["output"], "FAKE-1");
        assert_eq!(scene["layers"][0]["source"]["label"], "GIGA-BYTE GS27QA");
        assert_eq!(scene["layers"][1]["source"]["device"], "/dev/fake0");
        assert_eq!(scene["audio"][0]["source"], FAKE_MIC);
        assert_eq!(scene["audio"][1]["source"], FAKE_MONITOR);
        assert_eq!(scene["audio"][1]["gainDb"], -6.0);
        // The media is what the facts say.
        let screen = ffprobe(&dir.join("takes/take-0008/L1-screen-FAKE-1.mkv"));
        assert_eq!(screen["streams"][0]["width"], 640);
        assert_eq!(screen["streams"][0]["nb_read_packets"], "3105");
        let camera = ffprobe(&dir.join("takes/take-0008/L2-camera-0.mkv"));
        assert_eq!(camera["streams"][0]["height"], 240);
        // Take 5's A1 is silent where BRIEF §3.3 hatches it.
        let silences = detect_silences(&dir.join("takes/take-0005/A1-mic.mka"), -35.0, 400);
        assert_eq!(silences.len(), 2, "{silences:?}");
        assert!((silences[0].0 - 4.0).abs() < 0.002, "{silences:?}");
        assert!((silences[1].1 - 10.1).abs() < 0.002, "{silences:?}");
    }

    #[test]
    fn variants() {
        let env = TestEnv::new();
        let landed = design_fixture(&env.empty_dir("landed"), DesignVariant::Take10Landed);
        let take10 = &landed.takes[&TakeId::numbered(10)];
        assert_eq!(take10.duration_frames, TAKE_10_FRAMES);
        assert!(take10.placed && take10.status == TakeStatus::Ok);
        let last = landed.timeline.clips.last().unwrap();
        assert_eq!(
            (last.id.as_str(), last.in_, last.out),
            (TAKE_10_CLIP, 0, TAKE_10_FRAMES)
        );
        assert_eq!(landed.timeline.clips.len(), 11);
        assert_eq!(landed.next_take_number, 11);
        let total: u64 = landed.timeline.clips.iter().map(|c| c.out - c.in_).sum();
        assert_eq!(total, 12_233, "00:06:47:23");

        let dir = env.empty_dir("missing");
        let missing = design_fixture(&dir, DesignVariant::MissingL2);
        let take5 = &missing.takes[&TakeId::numbered(5)];
        assert!(
            take5
                .scene
                .layers
                .iter()
                .any(|l| l.id.as_str() == "L2" && l.missing)
        );
        assert!(take5.stream("L2").is_none());
        assert!(!dir.join("takes/take-0005/L2-camera-0.mkv").exists());

        let smoke = design_fixture(&env.empty_dir("smoke"), DesignVariant::Smoke);
        let clips: Vec<(&str, u64)> = smoke
            .timeline
            .clips
            .iter()
            .map(|c| (c.id.as_str(), c.out - c.in_))
            .collect();
        assert_eq!(clips, [("c7f3", 30), ("c1b2", 30), ("c3e9", 30)]);
        assert_eq!(smoke.takes.len(), 9);
    }

    #[test]
    fn the_perf_fixture_uses_one_file_per_kind() {
        let env = TestEnv::new();
        let dir = env.empty_dir("perf");
        let project = perf_fixture(&dir, 300);
        assert_eq!(project.timeline.clips.len(), 300);
        assert_eq!(project.takes.len(), 8);
        assert!(
            qrec_core::validate::validate(&project)
                .iter()
                .all(|i| { i.severity != qrec_core::validate::Severity::Error })
        );
        // Every take links (or, across file systems, copies) the same file.
        let bytes = |take: u32| {
            fs::read(dir.join(format!("takes/take-000{take}/L1-screen-FAKE-1.mkv"))).unwrap()
        };
        assert_eq!(bytes(1), bytes(8));
    }

    #[test]
    fn ui_presets_are_read_back() {
        let env = TestEnv::new();
        let dir = env.empty_dir("ui");
        let ui = UiState {
            playhead: 2437,
            bin_open: true,
            ..UiState::default()
        };
        write_ui(&dir, &ui);
        let back: UiState =
            serde_json::from_slice(&fs::read(dir.join(".qrec/ui.json")).unwrap()).unwrap();
        assert_eq!(back, ui);
    }

    /// Heavy (a minute of 1440p video the first time): run by hand.
    #[test]
    #[ignore]
    fn the_playback_fixture() {
        let env = TestEnv::new();
        let dir = env.empty_dir("playback");
        let project = playback_fixture(&dir);
        let take = &project.takes[&TakeId::numbered(1)];
        let sizes: Vec<(Option<u32>, Option<u32>)> =
            take.streams.iter().map(|s| (s.width, s.height)).collect();
        assert_eq!(
            sizes[..3],
            [
                (Some(2560), Some(1440)),
                (Some(2560), Some(1440)),
                (Some(1280), Some(720))
            ]
        );
        let probe = ffprobe(&dir.join("takes/take-0001/L2-screen-FAKE-2.mkv"));
        assert_eq!(probe["streams"][0]["nb_read_packets"], "1800");
    }
}
